static_assert(SOLVER_SHAPER_LUT_SIZE == 65535u, "compact shaper covers non-zero Q16 inputs only");
static_assert(SOLVER_LUT_SIZE <= 65535u, "compact state indices must fit uint16_t");

static constexpr uint16_t SOLVER_BLACK_STATE_INDEX = 0xFFFFu;
static inline bool solverInputIsBelowFirstState(uint16_t q16, uint8_t storageChannel) {
    if (NUM_CHANNELS == 0u || q16 == 0u) return true;
    const uint8_t channel = (storageChannel < NUM_CHANNELS) ? storageChannel : uint8_t(NUM_CHANNELS - 1u);
    return q16 < SOLVER_FIRST_STATE_Q16[channel];
}

// Returns SOLVER_BLACK_STATE_INDEX when q16 is below the first valid temporal state.
static inline uint16_t solverNonBlackStateIndexFromQ16(uint16_t q16, uint8_t storageChannel) {
    if (NUM_CHANNELS == 0u || q16 == 0u) return SOLVER_BLACK_STATE_INDEX;
    const uint8_t channel = (storageChannel < NUM_CHANNELS) ? storageChannel : uint8_t(NUM_CHANNELS - 1u);
    if (q16 < SOLVER_FIRST_STATE_Q16[channel]) return SOLVER_BLACK_STATE_INDEX;
    const uint16_t stateCount = SOLVER_STATE_COUNT[channel];
    if (stateCount == 0u) return SOLVER_BLACK_STATE_INDEX;
    uint16_t stateIndex = solverStateIndexShaperLUT[channel][uint16_t(q16 - 1u)];
    if (stateIndex >= stateCount) stateIndex = uint16_t(stateCount - 1u);
    return stateIndex;
}

